import {zipSync,strToU8} from 'fflate';
const escape=value=>value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
/** Independent minimal OOXML: two visible sheets, merge/styles, deliberately
 * wrong cached formula value, and conditional formatting the viewer must flag. */
export function previewXlsx(label='AUTHORED_SHEET',defaultHeight){
 const parts={
  '[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+[1,2].map(n=>'<Override PartName="/xl/worksheets/sheet'+n+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>',
  '_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
  'xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView activeTab="0"/></bookViews><sheets><sheet name="Values" sheetId="1" r:id="rId1"/><sheet name="Second" sheetId="2" r:id="rId2"/></sheets></workbook>',
  'xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+[1,2].map(n=>'<Relationship Id="rId'+n+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'+n+'.xml"/>').join('')+'<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',
  'xl/styles.xml':'<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><sz val="12"/><color rgb="FF102040"/><name val="Arial"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFE080"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/><xf numFmtId="2" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs></styleSheet>',
  'xl/worksheets/sheet1.xml':'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="A1:C40"/><sheetViews><sheetView workbookViewId="0"/></sheetViews>'+(defaultHeight===undefined?'':'<sheetFormatPr defaultRowHeight="'+defaultHeight+'"/>')+'<cols><col min="1" max="1" width="28" customWidth="1"/><col min="2" max="3" width="16" customWidth="1"/></cols><sheetData><row r="1" ht="24" customHeight="1"><c r="A1" t="inlineStr" s="1"><is><t>'+escape(label)+'</t></is></c></row><row r="2"><c r="A2"><f>1+2</f><v>99</v></c><c r="B2" s="2"><v>12.5</v></c><c r="C2"><f>WEBSERVICE(&quot;https://external.invalid/never-request&quot;)</f></c></row><row r="3" hidden="1"><c r="A3" t="inlineStr"><is><t>HIDDEN_AUTHORED_ROW</t></is></c></row><row r="40"><c r="A40" t="inlineStr"><is><t>AUTHORED_BOTTOM</t></is></c></row></sheetData><mergeCells count="1"><mergeCell ref="A1:C1"/></mergeCells><conditionalFormatting sqref="B2"><cfRule type="cellIs" priority="1" operator="greaterThan"><formula>0</formula></cfRule></conditionalFormatting></worksheet>',
  'xl/worksheets/sheet2.xml':'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>AUTHORED_SECOND_SHEET</t></is></c></row></sheetData></worksheet>',
 };
 return zipSync(Object.fromEntries(Object.entries(parts).map(([name,value])=>[name,strToU8('<?xml version="1.0" encoding="UTF-8"?>'+value)])),{level:6,mtime:new Date(2000,0,1)});
}
/** Independent raw BIFF8 records, not generated by the parser under test. */
export function previewXls(){
 const rec=(type,body)=>{const head=Buffer.alloc(4);head.writeUInt16LE(type);head.writeUInt16LE(body.length,2);return Buffer.concat([head,body]);};
 const bof=type=>{const body=Buffer.alloc(16);body.writeUInt16LE(0x0600);body.writeUInt16LE(type,2);body.writeUInt16LE(0x0dbb,4);body.writeUInt16LE(0x07cc,6);body.writeUInt32LE(0x41,8);body.writeUInt32LE(6,12);return rec(0x0809,body);};
 const name=Buffer.from('Legacy'),bound=Buffer.alloc(8+name.length);bound[6]=name.length;name.copy(bound,8);const cp=Buffer.alloc(2);cp.writeUInt16LE(1252);
 const globals=[bof(5),rec(0x0042,cp),rec(0x0085,bound),rec(0x000a,Buffer.alloc(0))];bound.writeUInt32LE(globals.reduce((sum,value)=>sum+value.length,0));globals[2]=rec(0x0085,bound);
 const text=Buffer.from('AUTHORED_LEGACY_XLS'),label=Buffer.alloc(9+text.length);label.writeUInt16LE(text.length,6);text.copy(label,9);const number=Buffer.alloc(14);number.writeUInt16LE(1);number.writeDoubleLE(42,6);
 return Buffer.concat([...globals,bof(0x0010),rec(0x0204,label),rec(0x0203,number),rec(0x000a,Buffer.alloc(0))]);
}
